import os
import subprocess
import shutil

# Define paths
source_dir = "/root/papers/all/"
dest_base = "/root/papers/"
subjects = ["LLM", "trapped_ion_and_qc", "black_hole", "DNA", "music_history"]

# Keywords for categorization
keywords = {
    "LLM": ["large language model", "transformer", "gpt", "bert", "nlp", "llm", "language model", "pre-training", "fine-tuning", "attention mechanism"],
    "trapped_ion_and_qc": ["trapped ion", "quantum computing", "qubit", "entanglement", "ion trap", "quantum gate", "paul trap", "quantum information"],
    "black_hole": ["black hole", "event horizon", "hawking radiation", "schwarzschild", "general relativity", "accretion disk", "kerr metric"],
    "DNA": ["dna", "genome", "sequencing", "nucleotide", "crispr", "gene", "polymerase", "chromosome", "genetics"]
}

def get_text_content(file_path):
    ext = os.path.splitext(file_path)[1].lower()
    if ext == ".pdf":
        try:
            # Extract first 2 pages to be efficient
            result = subprocess.run(["pdftotext", "-f", "1", "-l", "2", file_path, "-"], capture_output=True, text=True)
            return result.stdout.lower()
        except Exception as e:
            print(f"Error reading PDF {file_path}: {e}")
            return ""
    elif ext == ".pptx" or ext == ".docx":
        # For pptx and docx, since we don't have direct tools, we can try to grep inside the zip
        try:
            # Unzip to stdout and grep
            result = subprocess.run(["unzip", "-p", file_path], capture_output=True, text=True, errors='ignore')
            return result.stdout.lower()
        except Exception as e:
            print(f"Error reading ZIP-based file {file_path}: {e}")
            return ""
    return ""

def categorize(file_path, text):
    # Also check filename
    filename = os.path.basename(file_path).lower()

    # Check subjects in order
    for subject in ["LLM", "trapped_ion_and_qc", "black_hole", "DNA"]:
        for kw in keywords[subject]:
            if kw in text or kw in filename:
                return subject

    # Default to music_history
    return "music_history"

files = [f for f in os.listdir(source_dir) if os.path.isfile(os.path.join(source_dir, f))]

for filename in files:
    file_path = os.path.join(source_dir, filename)
    text = get_text_content(file_path)
    subject = categorize(file_path, text)

    dest_dir = os.path.join(dest_base, subject)
    shutil.move(file_path, os.path.join(dest_dir, filename))
    print(f"Moved {filename} to {subject}")

print("Organization complete.")

